import csv

# Series IDs
sensor_ts = "c49bbc2f-096e-5e16-bead-066250790308"  # Zone Air Temperature Sensor
heat_sp_ts = "dcb57f97-6711-5249-9f6f-3a81a69fc8d6"  # Heating Setpoint
cool_sp_ts = "c9fc3c98-8ad8-5bba-a072-0a5c02357f48"   # Cooling Setpoint

target_date = "2018-07-04"

def read_series(ts_id):
    rows = {}
    with open(VALUES_CSV) as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['timeseries_id'] == ts_id and row['timestamp'].startswith(target_date):
                rows[row['timestamp']] = float(row['value'])
    return rows

sensor = read_series(sensor_ts)
heat_sp = read_series(heat_sp_ts)
cool_sp = read_series(cool_sp_ts)

print(f"Sensor readings: {len(sensor)}")
print(f"Heating setpoint readings: {len(heat_sp)}")
print(f"Cooling setpoint readings: {len(cool_sp)}")

if not sensor:
    print("No sensor data available for the target date.")
else:
    violations = []
    for ts in sorted(sensor.keys()):
        s = sensor[ts]
        h = heat_sp.get(ts)
        c = cool_sp.get(ts)
        if h is None or c is None:
            violations.append((ts, s, h, c, "missing setpoint"))
        elif not (h <= s <= c):
            violations.append((ts, s, h, c, "out of range"))

    if violations:
        print(f"\nVIOLATIONS FOUND: {len(violations)}")
        for v in violations[:10]:
            print(f"  {v[0]}: sensor={v[1]}, heat_sp={v[2]}, cool_sp={v[3]}, reason={v[4]}")
        print("Answer: false")
    else:
        print("All sensor values within setpoints.")
        print("Answer: true")

    # Print some sample values
    for ts in sorted(sensor.keys())[:5]:
        print(f"  {ts}: sensor={sensor[ts]}, heat_sp={heat_sp.get(ts)}, cool_sp={cool_sp.get(ts)}")
